<?php require 'header.php';$p=db();$st=$p->prepare('SELECT * FROM users WHERE id=?');$st->execute([current_user_id()]);$u=$st->fetch();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=$_POST['old_password']??'';$new=$_POST['new_password']??'';$new2=$_POST['new_password2']??'';if(!password_verify($old,$u['password']))$err='La contraseña actual no es correcta.';elseif(strlen($new)<10)$err='La nueva contraseña debe tener al menos 10 caracteres.';elseif($new!==$new2)$err='Las contraseñas nuevas no coinciden.';else{$p->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),current_user_id()]);audit('CAMBIO_CLAVE','El usuario modificó su propia contraseña');send_app_mail($u['email']??'','Contraseña modificada','<p>Su contraseña del Planificador Gantt DRALA fue modificada correctamente.</p>');$msg='Contraseña modificada correctamente.';}}?><div class="page-title"><div><h1>Mi cuenta</h1><p><?=h($u['name'])?> · <?=h($u['email']??'Sin correo')?> · <?=h($u['department']??'Sin departamento')?></p></div></div><?php if($msg):?><div class="ok"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="bad"><?=h($err)?></div><?php endif;?><section class="panel"><h2>Cambiar mi contraseña</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Contraseña actual<input type="password" name="old_password" required></label><label>Nueva contraseña<input type="password" name="new_password" minlength="10" required></label><label>Repetir nueva contraseña<input type="password" name="new_password2" minlength="10" required></label><button class="btn primary">Modificar contraseña</button></form><p><small>Por seguridad, la contraseña no se envía por correo. Se envía una notificación de cambio.</small></p></section><?php require 'footer.php';?>
